import { Pool } from "pg";
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

export async function placeOrder(userId: string, sku: string, qty: number) {
  const client = await pool.connect();          // ONE connection for the whole tx
  let broken: Error | undefined;
  try {
    await client.query("BEGIN");
    const stock = await client.query(
      "UPDATE products SET stock = stock - $1 WHERE sku = $2 AND stock >= $1",
      [qty, sku]
    );
    if (stock.rowCount === 0) throw new Error("OUT_OF_STOCK");
    const { rows } = await client.query(
      "INSERT INTO orders (user_id, sku, qty) VALUES ($1, $2, $3) RETURNING id",
      [userId, sku, qty]
    );
    await client.query(
      "INSERT INTO outbox (topic, payload) VALUES ('order.created', $1)",
      [JSON.stringify({ orderId: rows[0].id })]
    );
    await client.query("COMMIT");
    return rows[0].id as string;               // bigint arrives as a string in pg
  } catch (err) {
    // If ROLLBACK itself fails, the connection is unusable: do not reuse it
    await client.query("ROLLBACK").catch(e => { broken = e; });
    throw err;                                 // keep the ORIGINAL error
  } finally {
    client.release(broken);                    // passing an error destroys the client
  }
}

