import { Pool, PoolClient } from "pg";
const pool = new Pool();
const RETRYABLE = new Set(["40001", "40P01"]); // serialization failure, deadlock

export async function withSerializable<T>(
  fn: (c: PoolClient) => Promise<T>,
  maxAttempts = 5
): Promise<T> {
  for (let attempt = 1; ; attempt++) {
    const client = await pool.connect();
    try {
      await client.query("BEGIN ISOLATION LEVEL SERIALIZABLE");
      const result = await fn(client);
      await client.query("COMMIT");
      return result;
    } catch (err: any) {
      await client.query("ROLLBACK").catch(() => {});
      if (!RETRYABLE.has(err.code) || attempt >= maxAttempts) throw err;
    } finally {
      client.release();
    }
    // back off AFTER release, so a waiting retry does not hold a connection
    await new Promise(r => setTimeout(r, 2 ** attempt * 10 + Math.random() * 20));
  }
}

