const lastWriteAt = new Map<string, number>(); // userId -> ms

export function markWrite(userId: string) {
  lastWriteAt.set(userId, Date.now());
}

export function dbFor(userId: string) {
  const t = lastWriteAt.get(userId) ?? 0;
  return Date.now() - t < 5_000 ? primary : replica;
}

