import { Pool } from "pg";

// Created once per process (outside any request/handler)
export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 10,                        // x instances must fit max_connections
  idleTimeoutMillis: 30_000,
  connectionTimeoutMillis: 2_000, // fail fast instead of hanging forever
  maxLifetimeSeconds: 1800,       // recycle, e.g. after a failover
});

pool.on("error", err => console.error("idle client error", err)); // avoid crash

export async function getUser(id: number) {
  const { rows } = await pool.query("SELECT id, email FROM users WHERE id = $1", [id]);
  return rows[0];                 // pool.query checks out AND releases for you
}

export async function withClient<T>(fn: (c: import("pg").PoolClient) => Promise<T>) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } finally {
    client.release();             // the line that prevents pool leaks
  }
}

