import { pool } from "./db";

// BAD: 1 + N round trips
export async function listOrdersSlow() {
  const { rows: orders } = await pool.query("SELECT id, customer_id FROM orders LIMIT 50");
  for (const o of orders) {
    const { rows } = await pool.query("SELECT name FROM customers WHERE id = $1", [o.customer_id]);
    o.customerName = rows[0]?.name;
  }
  return orders;
}

// GOOD: 2 round trips, whatever the page size
export async function listOrders() {
  const { rows: orders } = await pool.query("SELECT id, customer_id FROM orders LIMIT 50");
  const ids = [...new Set(orders.map(o => o.customer_id))];
  const { rows: customers } = await pool.query(
    "SELECT id, name FROM customers WHERE id = ANY($1::bigint[])",
    [ids]                                   // one array parameter
  );
  const byId = new Map(customers.map(c => [c.id, c.name]));
  return orders.map(o => ({ ...o, customerName: byId.get(o.customer_id) }));
}

