-- 1) word search with ranking (name matches weigh more)
SELECT id, name, ts_rank(search, q) AS rank
FROM products, websearch_to_tsquery('english', 'iphone pro') q
WHERE search @@ q
ORDER BY rank DESC LIMIT 20;

-- 2) fallback for typos: compare with the closest WORD in the name.
--    similarity() compares whole strings: 'iphnoe' vs 'iPhone 15 Pro'
--    is 0.17, below the 0.3 default of %, so % would find nothing.
SET pg_trgm.word_similarity_threshold = 0.4;   -- default 0.6
SELECT id, name, word_similarity('iphnoe', name) AS score
FROM products
WHERE 'iphnoe' <% name
ORDER BY score DESC LIMIT 20;

